// Edit these values once. Other nodes read them from here.
return [
  {
    json: {
      // Discord channel > Edit Channel > Integrations > Webhooks > Copy Webhook URL
      discordWebhookUrl: 'PASTE_YOUR_DISCORD_WEBHOOK_URL_HERE',
      // MLB team ID. 121 is the New York Mets.
      teamId: 121,
      timezone: 'America/New_York',
      // Maximum number of headlines in one digest.
      maxStories: 8,
    },
  },
];

const { maxStories } = $('Settings').first().json;
const cutoff = DateTime.now().minus({ hours: 24 });

const stories = $input
  .all()
  .map((item) => item.json)
  .filter((s) => s.isoDate && DateTime.fromISO(s.isoDate) >= cutoff)
  .slice(0, maxStories);

// No new stories: return nothing, so no message is posted.
if (stories.length === 0) return [];

// Wrap links in <> so Discord does not show a large preview for each one.
const lines = stories.map((s) => `• **${s.title}**\n  <${s.link}>`);

let message = ['📰 **Mets News - Last 24 Hours**', '', ...lines].join('\n');
// Discord rejects messages longer than 2000 characters.
if (message.length > 2000) message = message.slice(0, 1997) + '...';

return [{ json: { message } }];
